const LEDGER_DECODE_BLOCK_SIZE = 64 * 1024;

function ledgerIsWhitespaceOnly(text) {
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i);
    if (code !== 0x20 && code !== 0x09 && code !== 0x0d && code !== 0x0a) {
      return false;
    }
  }
  return true;
}

async function visitLedger(stream, visitor) {
  const decoder = new TextDecoder("utf-8", { fatal: true });
  const reader = stream.getReader();

  let accepted = 0;
  let rejected = 0;
  let physicalLine = 1;
  let cancelRequired = true;
  const currentParts = [];

  function takeCurrentLine() {
    let text = "";

    if (currentParts.length === 1) {
      text = currentParts[0];
    } else if (currentParts.length > 1) {
      text = currentParts.join("");
    }

    currentParts.length = 0;
    return text;
  }

  async function processLine(rawLine) {
    const lineText = rawLine.endsWith("\r")
      ? rawLine.slice(0, -1)
      : rawLine;

    if (ledgerIsWhitespaceOnly(lineText)) {
      return false;
    }

    let value;
    try {
      value = JSON.parse(lineText);
    } catch {
      rejected++;
      return false;
    }

    accepted++;
    return (await visitor({ line: physicalLine, value })) === false;
  }

  async function consumeText(text) {
    let start = 0;

    while (true) {
      const newline = text.indexOf("\n", start);
      if (newline === -1) {
        break;
      }

      if (newline > start) {
        currentParts.push(text.slice(start, newline));
      }

      const lineText = takeCurrentLine();
      if (await processLine(lineText)) {
        return true;
      }

      physicalLine++;
      start = newline + 1;
    }

    if (start < text.length) {
      currentParts.push(text.slice(start));
    }

    return false;
  }

  try {
    while (true) {
      const { done, value } = await reader.read();

      if (done) {
        if (await consumeText(decoder.decode())) {
          cancelRequired = false;
          return { accepted, rejected, stopped: true };
        }

        if (currentParts.length > 0) {
          const lineText = takeCurrentLine();
          if (await processLine(lineText)) {
            cancelRequired = false;
            return { accepted, rejected, stopped: true };
          }
        }

        cancelRequired = false;
        return { accepted, rejected, stopped: false };
      }

      for (
        let offset = 0;
        offset < value.byteLength;
        offset += LEDGER_DECODE_BLOCK_SIZE
      ) {
        const end = Math.min(
          offset + LEDGER_DECODE_BLOCK_SIZE,
          value.byteLength
        );
        const text = decoder.decode(value.subarray(offset, end), {
          stream: true
        });

        if (await consumeText(text)) {
          return { accepted, rejected, stopped: true };
        }
      }
    }
  } finally {
    try {
      if (cancelRequired) {
        await reader.cancel();
      }
    } finally {
      reader.releaseLock();
    }
  }
}
